"""
JavaScript runtime generation for entity-aware calculations.

This module generates JavaScript code that includes:
- Entity model (Situation, EntityModel classes)
- Aggregation functions (sum, any, max, min, count)
- Broadcasting functions (household → person)
- Helper utilities

The generated runtime enables compiled calculators to handle
complex multi-person, multi-household scenarios correctly.
"""

JS_ENTITY_RUNTIME = """
/**
 * PolicyEngine Entity Model Runtime
 *
 * Handles multi-person households with proper aggregation and broadcasting.
 * Generated by pe-compile.
 */

/**
 * Create an entity model from a situation.
 * @param {Object} situation - PE-style situation object
 * @returns {Object} Entity model with helper methods
 */
function createEntityModel(situation) {
  const people = situation.people || {};
  const households = situation.households || {};

  const personIds = Object.keys(people);
  const householdIds = Object.keys(households);

  // Build person → household mapping
  const personToHH = {};
  const hhIdToIdx = {};
  householdIds.forEach((hhId, idx) => {
    hhIdToIdx[hhId] = idx;
    const members = households[hhId].members || [];
    members.forEach(personId => {
      personToHH[personId] = hhId;
    });
  });

  return {
    people,
    households,
    personIds,
    householdIds,
    nPeople: personIds.length,
    nHouseholds: householdIds.length,

    /**
     * Get person-level variable as array.
     * @param {string} name - Variable name
     * @param {*} defaultValue - Default if not specified
     * @returns {Array} Values indexed by person
     */
    getPersonVariable(name, defaultValue = 0) {
      return personIds.map(pid => {
        const value = people[pid][name];
        return value !== undefined ? value : defaultValue;
      });
    },

    /**
     * Get household-level variable as array.
     * @param {string} name - Variable name
     * @param {*} defaultValue - Default if not specified
     * @returns {Array} Values indexed by household
     */
    getHouseholdVariable(name, defaultValue = 0) {
      return householdIds.map(hhId => {
        const value = households[hhId][name];
        return value !== undefined ? value : defaultValue;
      });
    },

    /**
     * Get person → household index mapping.
     * @returns {Array<number>} Household index for each person
     */
    personToHouseholdIndex() {
      return personIds.map(pid => hhIdToIdx[personToHH[pid]]);
    },

    /**
     * Set calculated person variable.
     * @param {string} name - Variable name
     * @param {Array} values - Values to set
     */
    setPersonVariable(name, values) {
      personIds.forEach((pid, idx) => {
        people[pid][name] = values[idx];
      });
    },

    /**
     * Set calculated household variable.
     * @param {string} name - Variable name
     * @param {Array} values - Values to set
     */
    setHouseholdVariable(name, values) {
      householdIds.forEach((hhId, idx) => {
        households[hhId][name] = values[idx];
      });
    },
  };
}

/**
 * Sum person values to household level.
 * Equivalent to: household.sum(household.members("variable", period))
 * @param {Array<number>} personValues - Values for each person
 * @param {Array<number>} personToHH - Person to household index mapping
 * @param {number} nHouseholds - Number of households
 * @returns {Array<number>} Sum per household
 */
function aggregateSum(personValues, personToHH, nHouseholds) {
  const result = new Array(nHouseholds).fill(0);
  personValues.forEach((value, personIdx) => {
    result[personToHH[personIdx]] += value;
  });
  return result;
}

/**
 * Check if any person in household has true value.
 * Equivalent to: household.any(household.members("is_disabled", period))
 * @param {Array<boolean>} personValues - Boolean for each person
 * @param {Array<number>} personToHH - Person to household index mapping
 * @param {number} nHouseholds - Number of households
 * @returns {Array<boolean>} True if any member is true
 */
function aggregateAny(personValues, personToHH, nHouseholds) {
  const result = new Array(nHouseholds).fill(false);
  personValues.forEach((value, personIdx) => {
    if (value) result[personToHH[personIdx]] = true;
  });
  return result;
}

/**
 * Get maximum person value per household.
 * Equivalent to: household.max(household.members("age", period))
 * @param {Array<number>} personValues - Values for each person
 * @param {Array<number>} personToHH - Person to household index mapping
 * @param {number} nHouseholds - Number of households
 * @returns {Array<number>} Max per household
 */
function aggregateMax(personValues, personToHH, nHouseholds) {
  const result = new Array(nHouseholds).fill(-Infinity);
  personValues.forEach((value, personIdx) => {
    const hhIdx = personToHH[personIdx];
    if (value > result[hhIdx]) result[hhIdx] = value;
  });
  return result;
}

/**
 * Get minimum person value per household.
 * Equivalent to: household.min(household.members("age", period))
 * @param {Array<number>} personValues - Values for each person
 * @param {Array<number>} personToHH - Person to household index mapping
 * @param {number} nHouseholds - Number of households
 * @returns {Array<number>} Min per household
 */
function aggregateMin(personValues, personToHH, nHouseholds) {
  const result = new Array(nHouseholds).fill(Infinity);
  personValues.forEach((value, personIdx) => {
    const hhIdx = personToHH[personIdx];
    if (value < result[hhIdx]) result[hhIdx] = value;
  });
  return result;
}

/**
 * Count people per household.
 * Equivalent to: household.nb_persons()
 * @param {Array<number>} personToHH - Person to household index mapping
 * @param {number} nHouseholds - Number of households
 * @returns {Array<number>} Count per household
 */
function aggregateCount(personToHH, nHouseholds) {
  const result = new Array(nHouseholds).fill(0);
  personToHH.forEach(hhIdx => {
    result[hhIdx]++;
  });
  return result;
}

/**
 * Broadcast household values to person level.
 * Equivalent to: person.household("household_income", period)
 * @param {Array} householdValues - Values for each household
 * @param {Array<number>} personToHH - Person to household index mapping
 * @returns {Array} Values for each person (from their household)
 */
function broadcastToMembers(householdValues, personToHH) {
  return personToHH.map(hhIdx => householdValues[hhIdx]);
}

/**
 * Element-wise operations on arrays.
 */
const arrayOps = {
  add: (a, b) => a.map((v, i) => v + (Array.isArray(b) ? b[i] : b)),
  sub: (a, b) => a.map((v, i) => v - (Array.isArray(b) ? b[i] : b)),
  mul: (a, b) => a.map((v, i) => v * (Array.isArray(b) ? b[i] : b)),
  div: (a, b) => a.map((v, i) => v / (Array.isArray(b) ? b[i] : b)),
  max: (a, b) => a.map((v, i) => Math.max(v, Array.isArray(b) ? b[i] : b)),
  min: (a, b) => a.map((v, i) => Math.min(v, Array.isArray(b) ? b[i] : b)),
  gt: (a, b) => a.map((v, i) => v > (Array.isArray(b) ? b[i] : b)),
  gte: (a, b) => a.map((v, i) => v >= (Array.isArray(b) ? b[i] : b)),
  lt: (a, b) => a.map((v, i) => v < (Array.isArray(b) ? b[i] : b)),
  lte: (a, b) => a.map((v, i) => v <= (Array.isArray(b) ? b[i] : b)),
  eq: (a, b) => a.map((v, i) => v === (Array.isArray(b) ? b[i] : b)),
  where: (cond, a, b) => cond.map((c, i) => c ? (Array.isArray(a) ? a[i] : a) : (Array.isArray(b) ? b[i] : b)),
};
"""


def get_js_runtime() -> str:
    """Get the JavaScript entity runtime code."""
    return JS_ENTITY_RUNTIME


def generate_js_with_runtime(
    calculations: str,
    include_runtime: bool = True,
) -> str:
    """
    Generate complete JS module with entity runtime.

    Args:
        calculations: The calculation code
        include_runtime: Whether to include the runtime (or import it)

    Returns:
        Complete JavaScript module
    """
    if include_runtime:
        return JS_ENTITY_RUNTIME + "\n\n" + calculations
    else:
        return (
            "import { createEntityModel, aggregateSum, aggregateAny, "
            "aggregateMax, aggregateMin, aggregateCount, broadcastToMembers, "
            "arrayOps } from './pe-runtime.js';\n\n" + calculations
        )
